using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;

namespace ProdOp;

public static class MathOps
{
    /// <summary>Computes the product of all elements using SIMD acceleration.</summary>
    public static float Product(ReadOnlySpan<float> values)
    {
        if (values.IsEmpty) return 0f;

        int i = 0;

        // Try 512-bit SIMD (16 floats per iteration)
        if (Vector512.IsHardwareAccelerated && values.Length >= Vector512<float>.Count)
        {
            var vProduct = Vector512<float>.One;
            ReadOnlySpan<Vector512<float>> vectors = MemoryMarshal.Cast<float, Vector512<float>>(values);
            for (int v = 0; v < vectors.Length; v++)
                vProduct *= vectors[v];
            i = vectors.Length * Vector512<float>.Count;

            // Reduce 512 → scalar by splitting into two 256-bit halves
            var lo = vProduct.GetLower();
            var hi = vProduct.GetUpper();
            var combined256 = lo * hi;
            var lo128 = combined256.GetLower();
            var hi128 = combined256.GetUpper();
            var combined128 = lo128 * hi128;
            float product = combined128[0] * combined128[1] * combined128[2] * combined128[3];
            for (; i < values.Length; i++)
                product *= values[i];
            return product;
        }

        // Try 256-bit SIMD (8 floats per iteration)
        if (Vector256.IsHardwareAccelerated && values.Length >= Vector256<float>.Count)
        {
            var vProduct = Vector256<float>.One;
            ReadOnlySpan<Vector256<float>> vectors = MemoryMarshal.Cast<float, Vector256<float>>(values);
            for (int v = 0; v < vectors.Length; v++)
                vProduct *= vectors[v];
            i = vectors.Length * Vector256<float>.Count;

            var lo = vProduct.GetLower();
            var hi = vProduct.GetUpper();
            var combined = lo * hi;
            float product = combined[0] * combined[1] * combined[2] * combined[3];
            for (; i < values.Length; i++)
                product *= values[i];
            return product;
        }

        // Try 128-bit SIMD (4 floats per iteration)
        if (Vector128.IsHardwareAccelerated && values.Length >= Vector128<float>.Count)
        {
            var vProduct = Vector128<float>.One;
            ReadOnlySpan<Vector128<float>> vectors = MemoryMarshal.Cast<float, Vector128<float>>(values);
            for (int v = 0; v < vectors.Length; v++)
                vProduct *= vectors[v];
            i = vectors.Length * Vector128<float>.Count;

            float product = vProduct[0] * vProduct[1] * vProduct[2] * vProduct[3];
            for (; i < values.Length; i++)
                product *= values[i];
            return product;
        }

        // Scalar fallback with 4x unrolling to break dependency chains
        {
            float p0 = 1f, p1 = 1f, p2 = 1f, p3 = 1f;
            int limit = values.Length - 3;
            for (; i < limit; i += 4)
            {
                p0 *= values[i];
                p1 *= values[i + 1];
                p2 *= values[i + 2];
                p3 *= values[i + 3];
            }
            float product = p0 * p1 * p2 * p3;
            for (; i < values.Length; i++)
                product *= values[i];
            return product;
        }
    }
}

